import{_ as e,c as l,o as n,a3 as a}from"./chunks/framework.BusRvirq.js";const x=JSON.parse('{"title":"최종 검수 완료 확인서 및 시스템 인수증 (Final Acceptance Sign-off)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/10_Final_Acceptance_Signoff_template.html"}]]},"headers":[],"relativePath":"public/templates/10_Final_Acceptance_Signoff_template.md","filePath":"public/templates/10_Final_Acceptance_Signoff_template.md","lastUpdated":1790810085000}'),i={name:"public/templates/10_Final_Acceptance_Signoff_template.md"};function r(s,t,d,g,o,c){return n(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="최종-검수-완료-확인서-및-시스템-인수증-final-acceptance-sign-off" tabindex="-1">최종 검수 완료 확인서 및 시스템 인수증 (Final Acceptance Sign-off) <a class="header-anchor" href="#최종-검수-완료-확인서-및-시스템-인수증-final-acceptance-sign-off" aria-label="Permalink to “최종 검수 완료 확인서 및 시스템 인수증 (Final Acceptance Sign-off)”">​</a></h1><p>국가를 당사자로 하는 계약에 관한 법률 시행령 제55조(검사), 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령 제64조, 및 관련 소프트웨어 개발 용역계약 일반조건에 의거하여 계약 내용 전반에 대한 최종 검수를 완료하고 본 시스템 및 산출물을 정식 인수합니다.</p><hr><h3 id="_1-사업-및-계약-기본-정보" tabindex="-1">1. 사업 및 계약 기본 정보 <a class="header-anchor" href="#_1-사업-및-계약-기본-정보" aria-label="Permalink to “1. 사업 및 계약 기본 정보”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명 (계약건명)</strong></td><td style="text-align:left;">[공식 계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>계약 번호</strong></td><td style="text-align:left;">[계약 번호]</td></tr><tr><td style="text-align:left;"><strong>발주 기관 / 고객사</strong></td><td style="text-align:left;">[발주처 공식 법인명]</td></tr><tr><td style="text-align:left;"><strong>계약 상대자 (수행사)</strong></td><td style="text-align:left;">주식회사 엠파시 (대표이사: [ ])</td></tr><tr><td style="text-align:left;"><strong>총 계약 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>실제 완료 일자</strong></td><td style="text-align:left;">202 년 월 일 (납기 내 준공 완료)</td></tr><tr><td style="text-align:left;"><strong>총 계약 금액</strong></td><td style="text-align:left;">일금 [ ] 원 (VAT 포함)</td></tr><tr><td style="text-align:left;"><strong>금회 검수 금액</strong></td><td style="text-align:left;">일금 [ ] 원 (총 계약금액의 100%)</td></tr></tbody></table><hr><h3 id="_2-최종-납품-산출물-검수-내역" tabindex="-1">2. 최종 납품 산출물 검수 내역 <a class="header-anchor" href="#_2-최종-납품-산출물-검수-내역" aria-label="Permalink to “2. 최종 납품 산출물 검수 내역”">​</a></h3><p>본 사업의 제안요청서, 과업내용서 및 사업수행계획서에 명시된 필수 납품 산출물이 누락 없이 완비되었음을 검사하여 합격 판정합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">분류</th><th style="text-align:left;">세부 산출물 명칭</th><th style="text-align:center;">제출 형태</th><th style="text-align:center;">검사 결과</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>관리 산출물</strong></td><td style="text-align:left;">사업수행계획서, 착수계, 주간/월간 보고서, WBS 실적표</td><td style="text-align:center;">전자문서(PDF)</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">관리 서류 완비</td></tr><tr><td style="text-align:left;"><strong>요구/설계</strong></td><td style="text-align:left;">요구사항 정의서(SRS), 추적표(RTM), 화면설계서, ERD, API 명세</td><td style="text-align:center;">전자문서/웹</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">최신 형상 일치</td></tr><tr><td style="text-align:left;"><strong>소스 코드</strong></td><td style="text-align:left;">백엔드(Java/Spring), 프론트엔드(Vue 3), DB DDL/DML 일체</td><td style="text-align:center;">Git 저장소/USB</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">라이선스 무결성</td></tr><tr><td style="text-align:left;"><strong>테스트 산출물</strong></td><td style="text-align:left;">단위/통합 테스트 결과서, 보안 약점 진단 보고서, 성능 시험서</td><td style="text-align:center;">전자문서(PDF)</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">결함 0건 검증</td></tr><tr><td style="text-align:left;"><strong>이관 및 배포</strong></td><td style="text-align:left;">데이터 이관 검증서, Docker/K8s 배포 스크립트</td><td style="text-align:center;">전자문서/스크립트</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">정상 배포 확인</td></tr><tr><td style="text-align:left;"><strong>운영 및 교육</strong></td><td style="text-align:left;">시스템 관리자 매뉴얼, 사용자 매뉴얼, 교육 결과 보고서</td><td style="text-align:center;">전자문서/책자</td><td style="text-align:center;">[ v ] 합격</td><td style="text-align:left;">현업 교육 완료</td></tr></tbody></table><hr><h3 id="_3-검수-총평-및-합격-판정" tabindex="-1">3. 검수 총평 및 합격 판정 <a class="header-anchor" href="#_3-검수-총평-및-합격-판정" aria-label="Permalink to “3. 검수 총평 및 합격 판정”">​</a></h3><ol><li><strong>과업 완성도 검사</strong>: <ul><li>계약상 명시된 모든 기능적, 비기능적 요구사항이 충실히 구현되었으며, 실운영 환경에서 정상 가동됨을 확인함.</li></ul></li><li><strong>최종 검사 판정</strong>: <strong>[ 합 격 (Acceptance Passed) ]</strong><ul><li>상기와 같이 계약 이행이 성실히 완료되었음을 확인하고, 본 시스템 및 제반 산출물을 최종 인수함.</li></ul></li><li><strong>무상 하자보수 개시 안내</strong>: <ul><li>본 검수완료일(인수일) 익일부터 계약서에 명시된 <strong>[ 1 ] 년간의 무상 하자보수 의무 기간</strong>이 개시됨.</li><li>하자담보책임기간: 202 년 월 일 ~ 202 년 월 일 (1년간)</li></ul></li></ol><hr><h3 id="_4-대금-지급-승인" tabindex="-1">4. 대금 지급 승인 <a class="header-anchor" href="#_4-대금-지급-승인" aria-label="Permalink to “4. 대금 지급 승인”">​</a></h3><p>본 검수 합격 판정에 따라 계약 상대자(주식회사 엠파시)의 최종 준공 잔금 청구 절차 진행을 정식 승인합니다.</p><hr><p><strong>검수 완료일: 202 년 월 일</strong></p><p><strong>[검사원 / 발주처 검수책임자]</strong></p><ul><li>소속 부서: [ ]</li><li>직급 / 직책: [ ]</li><li>성명: [ ] (인)</li></ul><p><strong>[입회관 / 발주처 사업부서 총괄]</strong></p><ul><li>소속 부서: [ ]</li><li>직급 / 직책: [ ]</li><li>성명: [ ] (인)</li></ul><p><strong>[인계자 / 주식회사 엠파시 대표자]</strong></p><ul><li>상호명: 주식회사 엠파시</li><li>주소: [ ]</li><li>대표이사: [ ] (인)</li></ul>',23)])])}const y=e(i,[["render",r]]);export{x as __pageData,y as default};
